def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Step 1: Initialize the grid with 0s
    grid = [[0] * N for _ in range(N)]

    # Step 2: Fill in the grid with the given values
    for x, y, value in grid_values:
        grid[y][x] = value

    # Step 3: Calculate the sum of values collected on each path
    path1_sum = 0
    path2_sum = 0

    # Step 4: Find the maximum sum of values collected on both paths
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                path1_sum += grid[i][j]
                path2_sum += grid[i][j]
            elif i == 0:
                path1_sum += grid[i][j] + grid[i][j-1]
                path2_sum += grid[i][j] + grid[i-1][j]
            elif j == 0:
                path1_sum += grid[i][j] + grid[i-1][j]
                path2_sum += grid[i][j] + grid[i][j-1]
            else:
                path1_sum += max(grid[i][j], grid[i][j-1])
                path2_sum += max(grid[i][j], grid[i-1][j])

    # Step 5: Return the maximum sum of values collected on both paths
    return max(path1_sum, path2_sum)

