def decode(encoded: str, original: str, message: str) -> str:
    # Step 1: Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            return "Failed"

    # Step 2: Use the mapping to decode the message
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

